 919	(A^x_{a_i})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{\delta} I_{\reg{Alice}} \otimes ((B_i)^x_{a_i})_{\reg{Bob}}.
 920	\end{equation}
 921	Define the POVM measurement $\{J^x_{g_1, \ldots, g_k}\}$ as
 922	\begin{equation*}
 923	J^x_{a_1, \ldots, a_k} := (B_k)^x_{a_k} \cdots (B_2)^x_{a_2} \cdot (B_1)^x_{a_1} \cdot (B_2)^x_{a_2} \cdots (B_k)^x_{a_k}.
 924	\end{equation*}
 925	Then
 926	\begin{equation*}
 927	(A^x_{a_1, \ldots, a_k})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{\delta^{1/2}} I_{\reg{Alice}} \otimes (J^x_{a_1, \ldots, a_k})_{\reg{Bob}}.
 928	\end{equation*}
 929	\end{fact}
 930	\begin{proof}
 931	For each $1 \leq i \leq k$, 
 932	\Cref{eq:no-take-only-throw} implies that
 933	\begin{equation*}
 934	(A^x_{a_i})_{\reg{Alice}} \otimes I_{\reg{Bob}} \approx_{\delta} I_{\reg{Alice}} \otimes ((B_i)^x_{a_i})_{\reg{Bob}}.
 935	\end{equation*}
 936	Now, we repeatedly apply this using \Cref{fact:add-a-proj}:
 937	\begin{align*}
 938	(A^x_{a_1, \ldots, a_k})_{\reg{Alice}} \otimes I_{\reg{Bob}}
 939	& = (A^x_{a_k} \cdots A^x_{a_2} \cdot A^x_{a_1} \cdot A^x_{a_2} \cdots A^x_{a_{k}})_{\reg{Alice}} \otimes I_{\reg{Bob}}\\
 940	& \approx_{\delta} (A^x_{a_k} \cdots A^x_{a_2} \cdot A^x_{a_1} \cdot A^x_{a_2} \cdots A^x_{a_{k-1}})_{\reg{Alice}} \otimes ((B_k)^x_{a_k})_{\reg{Bob}}\\
 941	&\qquad\qquad\qquad \qquad \qquad \qquad \cdots\\
 942	& \approx_{\delta} I_{\reg{Alice}} \otimes ((B_k)^x_{a_k} \cdots (B_2)^x_{a_2} \cdot (B_1)^x_{a_1} \cdot (B_2)^x_{a_2} \cdots (B_k)^x_{a_k})_{\reg{Bob}}\\
 943	& = I_{\reg{Alice}} \otimes (J^x_{a_1, \ldots, a_k})_{\reg{Bob}}.
 944	\end{align*}
 945	The fact now follows from \Cref{fact:almost-agreement} and the fact that~$A$ is a projective measurement.
 946	\end{proof}
 947	
 948	Next, we extend \Cref{fact:sandwich} to the case of polynomial measurements (see \Cref{sec:classical-q-low-deg} below).
 949	These are structured measurements in which the prover returns the evaluation of a function sampled independently from their input.
 950	The goal is to retain this structure even after ``sandwiching" them together.
 951	
 952	\begin{fact}\label{fact:low-degree-sandwich}
 953	Let $k \geq 0$ be a constant.
 954	Let $\calD$ be a distribution on questions $x \in \calX$.
 955	For each $1 \leq i \leq k$, let $\calG_i$ be a set of functions $g_i : \calX \rightarrow \calR_i$.
 956	and let $\{G^i_g\}$ be a projective measurement with outcomes from this set.
 957	Suppose that the set $\calG_i$ has the following distance property:
 958	for any two nonequal $g_i, g_i' \in \calG_i$, the probability that $g_i(\bx) = g_i'(\bx)$, over a random $\bx \sim \calD$, is at most $\eps$.
 959	
 960	Let $\{A_{g_1, \ldots, g_k}\}$ be a projective measurement with outcomes $g_i \in \calF_i$.
 961	For each $1 \leq i \leq k$, suppose that
 962	\begin{equation}\label{eq:treat-yo-self}
 963	(A_{[g_i(x) = a_i]})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{\delta} I_{\reg{Alice}} \otimes (G^i_{[g_i(x)=a_i]})_{\reg{Bob}}.
 964	\end{equation}
 965	Define the POVM measurement $\{J_{g_1, \ldots, g_k}\}$ as
 966	\begin{equation*}
 967	J_{g_1, \ldots, g_k} := G^k_{g_k} \cdots G^2_{g_2} \cdot G^1_{g_1} \cdot G^2_{g_2} \cdots G^k_{g_k}.
 968	\end{equation*}
 969	Then
 970	\begin{equation*}
 971	(A_{[g_1(x), \ldots, g_k(x) = a_1, \ldots, a_k]})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{(\delta+\eps)^{1/2}} I_{\reg{Alice}} \otimes (J_{[g_1(x), \ldots, g_k(x) = a_1, \ldots, a_k]})_{\reg{Bob}}.
 972	\end{equation*}
 973	\end{fact}
 974	\begin{proof}
 975	Let $1 \leq i \leq k$.
 976	By~\Cref{eq:treat-yo-self},
 977	if Alice measures with~$A$, producing~$\bg_i$, and Bob measures with~$G^i$, producing~$\bg_i'$,
 978	then the probability that $\bg_i(\bx) \neq \bg_i'(\bx)$ is $O(\delta)$.
 979	Write $\eta$ for the probability that $\bg_i \neq \bg_i'$.
 980	Then we have the expression $\eta \cdot (1-\eps) \leq O(\delta)$ or, equivalently, $\eta \leq O(\delta/(1-\eps))$.
 981	When $\eps < 1/2$, this gives the bound $\eta \leq O(\delta)$, and when $\eps \geq 1/2$, we have the trivial bound $\eta \leq O(\eps)$.
 982	As a result, $\eta = O(\delta + \eps)$.
 983	
 984	In conclusion,
 985	\begin{equation*}
 986	(A_{g_i})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{\delta + \eps} I_{\reg{Alice}} \otimes (G^i_{g_i})_{\reg{Bob}}.
 987	\end{equation*}
 988	We can now apply \Cref{fact:sandwich} to $A_{g_1, \ldots, g_k}$ and the $G^i_{g_i}$ measurements.
 989	It implies that
 990	\begin{equation*}
 991	(A_{g_1, \ldots, g_k})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{(\delta+\eps)^{1/2}} I_{\reg{Alice}} \otimes (J_{g_1, \ldots, g_k})_{\reg{Bob}}.
 992	\end{equation*}
 993	The fact now follows from the data processing inequality \Cref{fact:specialize-the-simeq}.
 994	\end{proof}
 995	
 996	In our next fact, we show that \Cref{fact:low-degree-sandwich} holds even when we drop the structured assumption on the~$A$ matrix.
 997	The tradeoff is that we must now assume that the~$k$ different measurements act on different parts of the input string.
 998	In this case, the distance condition becomes slightly more cumbersome to state.
 999	
1000	\begin{fact}\label{fact:low-degree-sandwich-on-steroids}
1001	Let $k \geq 0$ be a constant.
1002	Let $\calD$ be a distribution on questions $(x, y_1, \ldots, y_k)$, where each $y_i \in \calY_i$.
1003	For each $1 \leq i \leq k$, let $\calG_i$ be a set of functions $g_i : \calY_i \rightarrow \calR_i$.
1004	and let $\{(G_i)^x_g\}$ be a projective measurement with outcomes from this set.
1005	(For the $i=1$ case, we also allow this measurement to be a POVM.)
1006	Suppose that the set $\calG_i$ has the following distance property:
1007	fix a question $z = (x, y_1, \ldots, y_{i-1}, y_{i+1}, \ldots, y_k)$, and let $\calD_z$ be the distribution on~$y_i$ conditioned on the other outcomes~$z$.
1008	Then for any two nonequal $g_i, g_i' \in \calG_i$, the probability that $g_i(\by_i) = g_i'(\by_i)$, over a random $\by_i \sim \calD_z$, is at most $\eps$.
1009	
1010	Let $\{A^{x, y_1, \ldots, y_k}_{a_1, \ldots, a_k} \}$ be a projective measurement with outcomes $g_i \in \calF_i$.
1011	For each $1 \leq i \leq k$, suppose that
1012	\begin{equation}\label{eq:gonna-compare-like-a-pear}
1013	(A^{x, y_1, \ldots, y_k}_{a_i})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{\delta} I_{\reg{Alice}} \otimes ((G_i)^x_{[g_i(y_i)=a_i]})_{\reg{Bob}}.
1014	\end{equation}
1015	Suppose also that
1016	\begin{equation}\label{eq:spend-some-time-reflecting}
1017	(A^{x, y_1, \ldots, y_k}_{a_1, \ldots, a_k})_{\reg{Alice}} \otimes I_{\reg{Bob}}
1018		\simeq_{\delta} I_{\reg{Alice}} \otimes (A^{x, y_1, \ldots, y_k}_{a_1, \ldots, a_k})_{\reg{Bob}}.
1019	\end{equation}
1020	Define the POVM measurement $\{J^x_{g_1, \ldots, g_k}\}$ as
1021	\begin{equation*}
1022	J^x_{g_1, \ldots, g_k} := (G_k)^x_{g_k} \cdots (G_2)^x_{g_2} \cdot (G_1)^x_{g_1} \cdot (G_2)^x_{g_2} \cdots (G_k)^x_{g_k}.
1023	\end{equation*}
1024	Then
1025	\begin{equation*}
1026	(A^{x, y_1, \ldots, y_k}_{a_1, \ldots, a_k})_{\reg{Alice}} \otimes I_{\reg{Bob}}
1027		\simeq_{\poly(\delta, \eps)} I_{\reg{Alice}} \otimes (J^x_{[g_1(y_1), \ldots, g_k(y_k) = a_1, \ldots, a_k]})_{\reg{Bob}}.
1028	\end{equation*}
1029	\end{fact}
1030	\begin{proof}
1031	First, we show how to reduce this to the $k = 2$ case. Then we prove it for that case.
1032	Assume the fact holds when $k = 2$.  Define the POVM measurement $\{(J_i)^x_{g_1, \ldots, g_i}\}$ as
1033	\begin{equation*}
1034	(J_i)^x_{g_1, \ldots, g_i} := (G_i)^x_{g_i} \cdots (G_2)^x_{g_2} \cdot (G_1)^x_{g_1} \cdot (G_2)^x_{g_2} \cdots (G_i)^x_{g_i}.
1035	\end{equation*}
1036	We will show by induction that 
1037	\begin{equation}\label{eq:hi-i-work-in-graphics-but-not-that-graphics}
1038	(A^{x, y_1, \ldots, y_k}_{a_1, \ldots, a_i})_{\reg{Alice}} \otimes I_{\reg{Bob}}
1039		\simeq_{\poly(\delta, \eps)} I_{\reg{Alice}} \otimes ((J_i)^x_{[g_1(y_1), \ldots, g_i(y_i) = a_1, \ldots, a_i]})_{\reg{Bob}},
1040	\end{equation}
1041	the base case being trivial. Assume this holds for~$i$.
1042	We apply the $k = 2$ case as follows:
1043	consider the question tuple $(y_1, \ldots, y_i)$ as a single question
1044	and consider functions of the form $(y_1, \ldots, y_i) \mapsto (g_1(y_1), \ldots, g_i(y_i))$.
1045	Then the first POVM measurement is $J_i$, which satisfies \Cref{eq:gonna-compare-like-a-pear} due to \Cref{eq:hi-i-work-in-graphics-but-not-that-graphics}.
1046	The second measurement is the projector $G_{i+1}$.
1047	Then the $k = 2$ case immediately implies the $i+1$ case of \Cref{eq:hi-i-work-in-graphics-but-not-that-graphics}.
1048	
1049	Now we prove the $k = 2$ case.
1050	Our goal is to show that
1051	\begin{equation}\label{eq:food-rakes}
1052	\E_{\bx, \by_1, \by_2} \sum_{a_1, g_2} \bra{\psi} (A^{\bx, \by_1, \by_2}_{a_1, g_2(\by_2)})_{\reg{Alice}}
1053	\otimes ((G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2})_{\reg{Bob}} \ket{\psi}
1054	\end{equation}
1055	is at least $1- \poly(\delta, \eps)$.
1056	We will do this by showing that
1057	\begin{equation}\label{eq:what-a-johnnie-wants}
1058	((G_1)^x_{[g_1(y_1)=a_1]} \cdot (G_2)^x_{g_2})_{\reg{Alice}} \otimes I_{\reg{Bob}}
1059	\approx_{\poly(\delta, \eps)} ((G_2)^x_{g_2} \cdot (G_1)^x_{[g_1(y_1)=a_1]})_{\reg{Alice}} \otimes I_{\reg{Bob}}.
1060	\end{equation}
1061	is at most $\poly(\delta, \eps)$.
1062	To see that this is sufficient, note that the related expression
1063	\begin{equation*}
1064	\E_{\bx, \by_1, \by_2} \sum_{a_1, g_2} \bra{\psi} (A^{\bx, \by_1, \by_2}_{a_1, g_2(\by_2)})_{\reg{Alice}}
1065	\otimes ((G_2)^{\bx}_{g_2} \cdot (G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]})_{\reg{Bob}} \ket{\psi}
1066	\end{equation*}
1067	is exactly equal to~$1$ because $G_2$ is a projector.
1068	Taking the difference between this and \Cref{eq:food-rakes}, we get
1069	\begin{equation*}
1070	\E_{\bx, \by_1, \by_2} \sum_{a_1, g_2} \bra{\psi} (A^{\bx, \by_1, \by_2}_{a_1, g_2(\by_2)})_{\reg{Alice}}
1071	\otimes ((G_2)^{\bx}_{g_2} \cdot ((G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2}- (G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]}))_{\reg{Bob}} \ket{\psi}.
1072	\end{equation*}
1073	Cauchy-Schwarz allows us to bound this by
1074	\begin{multline*}
1075	\leq \E_{\bx, \by_1, \by_2} \sqrt{ \sum_{a_1, g_2}\Vert (A^{\bx, \by_1, \by_2}_{a_1, g_2(\by_2)})_{\reg{Alice}} \otimes ((G_2)^{\bx}_{g_2})_{\reg{Bob}} \ket{\psi} \Vert^2}\\
1076		\cdot \sqrt{ \sum_{a_1, g_2}\Vert I_{\reg{Alice}} \otimes ((G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2}- (G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]})_{\reg{Bob}} \ket{\psi} \Vert^2}.
1077	\end{multline*}
1078	The expression inside the first square root is always at most~$1$.
1079	This allows us to bring the expectation into the second square root by Jensen's inequality,
1080	and the resulting expression we can bound due to \Cref{eq:what-a-johnnie-wants}.
1081	
1082	Now we bound \Cref{eq:what-a-johnnie-wants}.
1083	Showing this is small is equivalent to showing
1084	\begin{equation*}
1085	\E_{\bx, \by_1, \by_2}
1086	\sum_{a_1, g_2}\Vert ((G_1)^{\bx}_{[g_1(\by_1) = a_1]}
1087		\cdot (G_2)^{\bx}_{g_2}- (G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]})_{\reg{Alice}} \otimes I_{\reg{Bob}} \ket{\psi} \Vert^2
1088	\end{equation*}
1089	is small.  Expanding this, we get
1090	\begin{align}
1091	\E_{\bx, \by_1, \by_2} \sum_{a_1, g_2} \bra{\psi}\big(
1092		&(G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2} \otimes I_{\reg{Bob}}\nonumber\\
1093		+ &(G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2} \cdot (G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \otimes I_{\reg{Bob}}\nonumber\\
1094		- &(G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \otimes I_{\reg{Bob}}\nonumber\\
1095		- &(G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2} \otimes I_{\reg{Bob}} \big)\ket{\psi}.\label{eq:burger-king}
1096	\end{align}
1097	We \emph{do} know that $G_1$ and $G_2$ satisfy some form of commutation.
1098	Because they satisfy \Cref{eq:gonna-compare-like-a-pear} and~$A$ is a projector, 
1099	we know that
1100	\begin{equation*}
1101	((G_1)^x_{[g_1(y_1)=a_1]} \cdot (G_2)^x_{[g_2(y_2) = a_2]})_{\reg{Alice}} \otimes I_{\reg{Bob}}
1102	\approx_{\delta} ((G_2)^x_{[g_2(y_2) = a_2]} \cdot (G_1)^x_{[g_1(y_1)=a_1]})_{\reg{Alice}} \otimes I_{\reg{Bob}}.
1103	\end{equation*}
1104	Expanding this as above, we can bound the following expression by~$\delta$:
1105	\begin{align}
1106	\E_{\bx, \by_1, \by_2} \sum_{a_1, a_2} \bra{\psi}\big(
1107		&(G_2)^\bx_{[g_2(\by_2) = a_2]} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^\bx_{[g_2(\by_2) = a_2]} \otimes I_{\reg{Bob}}\nonumber\\
1108		+ &(G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^\bx_{[g_2(\by_2) = a_2]} \cdot (G_2)^\bx_{[g_2(\by_2) = a_2]} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \otimes I_{\reg{Bob}}\nonumber\\
1109		- &(G_2)^\bx_{[g_2(\by_2) = a_2]} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^\bx_{[g_2(\by_2) = a_2]} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \otimes I_{\reg{Bob}}\nonumber\\
1110		- &(G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^\bx_{[g_2(\by_2) = a_2]} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^\bx_{[g_2(\by_2) = a_2]}\otimes I_{\reg{Bob}} \big)\ket{\psi}.\label{eq:what-to-do-with-this}
1111	\end{align}
1112	We can therefore show \Cref{eq:burger-king} is small by
1113	upper-bounding (\Cref{eq:burger-king}$ - $\Cref{eq:what-to-do-with-this}).
1114	There are four terms in this difference;
1115	write $\Delta_i$ for the $i$-th term in \Cref{eq:burger-king} minus the $i$-th term in \Cref{eq:what-to-do-with-this}.
1116	We will bound each $\Delta_i$ one-by-one.
1117	
1118	The first term in the difference, $\Delta_1$, is
1119	\begin{multline*}
1120	\E_{\bx, \by_1, \by_2} \sum_{a_1}\sum_{g_2} \bra{\psi}
1121		(G_2)^{\bx}_{g_2}
1122		\cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2} \otimes I_{\reg{Bob}} \ket{\psi}\\
1123	-\E_{\bx, \by_1, \by_2} \sum_{a_1, a_2} \bra{\psi}
1124		(G_2)^{\bx}_{[g_2(\by_2) = a_2]}
1125		\cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{[g_2(\by_2) = a_2]} \otimes I_{\reg{Bob}} \ket{\psi}.
1126	\end{multline*}
1127	The first of these terms is at most~$1$, and so we just have to show that the second term is close to~$1$ as well.
1128	Note that by repeated applications of \Cref{eq:gonna-compare-like-a-pear}, we have that 
1129	\begin{equation*}
1130	(G_2)^{\bx}_{[g_2(\by_2) = a_2]}
1131		\cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{[g_2(\by_2) = a_2]} \otimes I_{\reg{Bob}}
1132		\approx_{\delta} I_{\reg{Alice}} \otimes A^{\bx, \by_1, \by_2}_{a_1, a_2}.
1133	\end{equation*}
1134	But then by \Cref{fact:approx-delta-generalized-game-value}, the expression we want to lower-bound is $O(\delta^{1/2})$-close to
1135	\begin{equation*}
1136	\E_{\bx, \by_1, \by_2} \sum_{a_1, a_2} \bra{\psi} I_{\reg{Alice}} \otimes A^{\bx, \by_1, \by_2}_{a_1, a_2} \ket{\psi},
1137	\end{equation*}
1138	which is exactly~$1$. As a result, $\Delta_1$ is at most $O(\delta^{1/2})$.
1139	
1140	The second term in the difference, $\Delta_2$, can be written as
1141	\begin{equation*}
1142	-\E_{\bx, \by_1, \by_2} \sum_{a_1}\sum_{\substack{g_2\neq g_2',\\g_2(\by_2) = g_2'(\by_2)}} \bra{\psi}(
1143		(G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2} \cdot (G_2)^{\bx}_{g_2'} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \otimes I_{\reg{Bob}})\ket{\psi}.
1144	\end{equation*}
1145	This is zero because $G_2$ is a projector.
1146	
1147	The third and fourth terms in \Cref{eq:burger-king} are complex conjugates of each other,
1148	as are the third and fourth terms in \Cref{eq:what-to-do-with-this}.
1149	As a result, it suffices to bound the magnitude of $\Delta_4$, and this will serve to bound $\Delta_3$ as well.
1150	We begin by manipulating the fourth term in \Cref{eq:burger-king};
1151	specifically, we will show that it is close to
1152	\begin{equation}\label{eq:cloud}
1153	-\E_{\bx, \by_1, \by_2} \sum_{a_1, g_2} \bra{\psi}
1154		 (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \otimes (G_2)^{\bx}_{g_2} \ket{\psi}.
1155	\end{equation}
1156	To do so, we take their difference:
1157	\begin{multline*}
1158	\E_{\bx, \by_1, \by_2} \sum_{a_1, g_2} \bra{\psi}
1159		 ((G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \otimes I_{\reg{Bob}})\\
1160		\cdot (I_{\reg{Alice}} \otimes  (G_2)^{\bx}_{g_2} - (G_2)^{\bx}_{g_2} \otimes I_{\reg{Bob}}) \ket{\psi}.
1161	\end{multline*}
1162	To bound the magnitude, we apply Cauchy-Schwarz:
1163	\begin{multline*}
1164	\E_{\bx, \by_1, \by_2}
1165		\sqrt{\sum_{a_1, g_1} \Vert  ((G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \otimes I_{\reg{Bob}}) \ket{\psi} \Vert^2}\\
1166		\cdot \sqrt{\sum_{a_1, g_1} \Vert ((G_1)^{\bx}_{[g_1(\by_1) = a_1]} \otimes I_{\reg{Bob}})
1167		\cdot (I_{\reg{Alice}} \otimes  (G_2)^{\bx}_{g_2} - (G_2)^{\bx}_{g_2} \otimes I_{\reg{Bob}}) \ket{\psi} \Vert^2}.
1168	\end{multline*}
1169	The expression inside the first square root is always at most~$1$.
1170	This allows us to bring the expectation into the second square root by Jensen's inequality.
